    public string? SpellCorrectionConfiguration { get; set; }

    /// <summary>
    /// Provides configuration to determine how to group results by document attribute value, and how to display them (collapsed or expanded) un- der a designated primary document for each group. DocumentAttributeKey -&gt; (string) [required] The document attribute used to group search results. You can use any attribute that has the Sortable flag set to true. You can also sort by any of the following built-in attributes:"_cate- gory","_created_at", "_last_updated_at", "_version", "_view_count". Constraints: o min: 1 o max: 200 o pattern: [a-zA-Z0-9_][a-zA-Z0-9_-]* SortingConfigurations -&gt; (list) A prioritized list of document attributes/fields that determine the primary document among those in a collapsed group. Constraints: o min: 1 (structure) Specifies the document attribute to use to sort the response to a Amazon Kendra query. You can specify a single attribute for sorting. The attribute must have the Sortable flag set to true , otherwise Amazon Kendra returns an exception. You can sort attributes of the following types. o Date value o Long value o String value You can't sort attributes of the following type. o String list value DocumentAttributeKey -&gt; (string) [required] The name of the document attribute used to sort the re- sponse. You can use any field that has the Sortable flag set to true. You can also sort by any of the following built-in at- tributes: o _category o _created_at o _last_updated_at o _version o _view_count Constraints: o min: 1 o max: 200 o pattern: [a-zA-Z0-9_][a-zA-Z0-9_-]* SortOrder -&gt; (string) [required] The order that the results should be returned in. In case of ties, the relevance assigned to the result by Amazon Kendra is used as the tie-breaker. Possible values: o DESC o ASC MissingAttributeKeyStrategy -&gt; (string) Specifies the behavior for documents without a value for the collapse attribute. Amazon Kendra offers three customization options: o Choose to COLLAPSE all documents with null or missing values in one group. This is the default configuration. o Choose to IGNORE documents with null or missing values. Ig- nored documents will not appear in query results. o Choose to EXPAND each document with a null or missing value into a group of its own. Possible values: o IGNORE o COLLAPSE o EXPAND Expand -&gt; (boolean) Specifies whether to expand the collapsed results. ExpandConfiguration -&gt; (structure) Provides configuration information to customize expansion op- tions for a collapsed group. MaxResultItemsToExpand -&gt; (integer) The number of collapsed search result groups to expand. If you set this value to 10, for example, only the first 10 out of 100 result groups will have expand functionality. MaxExpandedResultsPerItem -&gt; (integer) The number of expanded results to show per collapsed primary document. For instance, if you set this value to 3, then at most 3 results per collapsed group will be displayed. Shorthand Syntax: DocumentAttributeKey=string,SortingConfigurations=[{DocumentAttributeKey=string,SortOrder=string},{DocumentAttributeKey=string,SortOrder=string}],MissingAttributeKeyStrategy=string,Expand=boolean,ExpandConfiguration={MaxResultItemsToExpand=integer,MaxExpandedResultsPerItem=integer} JSON Syntax: { "DocumentAttributeKey": "string", "SortingConfigurations": [ { "DocumentAttributeKey": "string", "SortOrder": "DESC"|"ASC" } ... ], "MissingAttributeKeyStrategy": "IGNORE"|"COLLAPSE"|"EXPAND", "Expand": true|false, "ExpandConfiguration": { "MaxResultItemsToExpand": integer, "MaxExpandedResultsPerItem": integer } }
    /// </summary>
    [CliOption("--collapse-configuration")]
    public string? CollapseConfiguration { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

